app.post('/login', (req, res) => {
  const user = db.query("SELECT * FROM users WHERE email = '" + req.body.email + "' AND password = '" + req.body.password + "'");
  if (user) {
    res.cookie('session', req.body.email);
    res.json({ token: Buffer.from(req.body.email).toString('base64') });
  } else {
    res.status(401).send('Invalid credentials');
  }
});
